package com.mohymods.kingdomsmp.profession;

import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;

/** World-local native placement identities and completed walks share one bounded save. */
public final class MineAccessEvidence {
 public static final int MAX_MARKS=32768,PER_PLAYER=2048,MAX_ROUTE=512;
 public record Cell(String dimension,long position){public Cell{if(!"minecraft:overworld".equals(dimension))throw new IllegalArgumentException("Unvalidated mine dimension");}}
 public record Mark(UUID player,String block){public Mark{Objects.requireNonNull(player);if(!material(block))throw new IllegalArgumentException("Unvalidated mine material");}}
 public record Route(UUID id,String dimension,List<Long> cells){public Route{Objects.requireNonNull(id);new Cell(dimension,0);cells=List.copyOf(cells);if(cells.size()<2||cells.size()>MAX_ROUTE||new HashSet<>(cells).size()!=cells.size())throw new IllegalArgumentException("Invalid retained mine walk");if(BlockPos.of(cells.getFirst()).getY()<0||cells.stream().noneMatch(n->BlockPos.of(n).getY()<0)||!connected(cells))throw new IllegalArgumentException("Invalid mine descent topology");}}
 private static boolean connected(List<Long> cells){var pending=new HashSet<>(cells);var queue=new ArrayDeque<Long>();pending.remove(cells.getFirst());queue.add(cells.getFirst());while(!queue.isEmpty()){var pos=BlockPos.of(queue.removeFirst());for(int dx=-1;dx<=1;dx++)for(int dz=-1;dz<=1;dz++)if(Math.abs(dx)+Math.abs(dz)<=1)for(int dy=-1;dy<=1;dy++){long next=pos.offset(dx,dy,dz).asLong();if(pending.remove(next))queue.add(next);}}return pending.isEmpty();}
 private final Map<Cell,Mark> marks=new HashMap<>();private final Map<UUID,Integer> ownership=new HashMap<>();private final Map<UUID,Route> routes=new HashMap<>();
 public static boolean material(String id){if(id==null||!id.startsWith("minecraft:"))return false;String name=id.substring(10);for(var stone:List.of("cobblestone","stone","stone_brick","cobbled_deepslate","deepslate_brick","andesite","diorite","granite"))if(name.equals(stone)||name.equals(stone+"s")||name.equals(stone+"_stairs")||name.equals(stone+"_slab"))return true;for(var wood:TreeEvidence.SPECIES)if(name.equals(wood+"_planks")||name.equals(wood+"_stairs")||name.equals(wood+"_slab"))return true;return false;}
 public Optional<Mark> mark(Cell cell){return Optional.ofNullable(marks.get(cell));}public Optional<Route> route(UUID player){return Optional.ofNullable(routes.get(player));}
 public boolean record(Cell cell,Mark mark){if(marks.containsKey(cell))return false;if(marks.size()>=MAX_MARKS||ownership.getOrDefault(mark.player(),0)>=PER_PLAYER)return false;marks.put(cell,mark);ownership.merge(mark.player(),1,Integer::sum);return true;}
 public boolean remove(Cell cell){var mark=marks.remove(cell);if(mark==null)return false;ownership.computeIfPresent(mark.player(),(p,n)->n==1?null:n-1);return true;}
 public boolean complete(UUID player,String dimension,Walk walk,int required){if(!walk.returned(required))return false;var route=new Route(UUID.randomUUID(),dimension,walk.cells());if(required<2||required>MAX_ROUTE||route.cells().size()<required||!routes.containsKey(player)&&routes.size()>=128)return false;boolean below=false;for(long pos:route.cells()){var mark=marks.get(new Cell(route.dimension(),pos));if(mark==null||!mark.player().equals(player))return false;if(BlockPos.of(pos).getY()<0)below=true;}if(!below||BlockPos.of(route.cells().getFirst()).getY()<0)return false;routes.put(player,route);return true;}
 public CompoundTag save(){var tag=new CompoundTag();tag.putInt("schema",1);var rows=new ListTag();marks.entrySet().stream().sorted(Comparator.comparingLong(e->e.getKey().position())).forEach(e->{var row=new CompoundTag();row.putString("dimension",e.getKey().dimension());row.putLong("position",e.getKey().position());row.putUUID("player",e.getValue().player());row.putString("block",e.getValue().block());rows.add(row);});tag.put("marks",rows);var walks=new ListTag();routes.entrySet().stream().sorted(Map.Entry.comparingByKey()).forEach(e->{var row=new CompoundTag();row.putUUID("player",e.getKey());row.putUUID("id",e.getValue().id());row.putString("dimension",e.getValue().dimension());row.putLongArray("cells",e.getValue().cells());walks.add(row);});tag.put("routes",walks);return tag;}
 public static MineAccessEvidence load(CompoundTag tag){if(!tag.getAllKeys().equals(Set.of("schema","marks","routes"))||!tag.contains("schema",Tag.TAG_INT)||tag.getInt("schema")!=1)throw new IllegalArgumentException("Invalid mine access schema");var out=new MineAccessEvidence();for(var value:rows(tag,"marks",MAX_MARKS)){var row=(CompoundTag)value;if(!row.getAllKeys().equals(Set.of("dimension","position","player","block"))||!row.hasUUID("player")||!row.contains("dimension",Tag.TAG_STRING)||!row.contains("position",Tag.TAG_LONG)||!row.contains("block",Tag.TAG_STRING)||!out.record(new Cell(row.getString("dimension"),row.getLong("position")),new Mark(row.getUUID("player"),row.getString("block"))))throw new IllegalArgumentException("Invalid/duplicate retained mine cell");}for(var value:rows(tag,"routes",128)){var row=(CompoundTag)value;if(!row.getAllKeys().equals(Set.of("player","id","dimension","cells"))||!row.hasUUID("player")||!row.hasUUID("id")||!row.contains("dimension",Tag.TAG_STRING)||!row.contains("cells",Tag.TAG_LONG_ARRAY))throw new IllegalArgumentException("Invalid completed mine route");var route=new Route(row.getUUID("id"),row.getString("dimension"),Arrays.stream(row.getLongArray("cells")).boxed().toList());if(out.routes.put(row.getUUID("player"),route)!=null)throw new IllegalArgumentException("Duplicate mine route owner");}return out;}
 private static ListTag rows(CompoundTag tag,String key,int max){if(!(tag.get(key) instanceof ListTag rows)||rows.size()>max||!rows.isEmpty()&&rows.getElementType()!=Tag.TAG_COMPOUND)throw new IllegalArgumentException("Invalid mine access rows");return rows;}
 /** Transient continuous walk; a restart/teleport ends an unfinished trip, never erases retained material. */
 public static final class Walk {
  private final long entry;private long last;private final LinkedHashSet<Long> visited=new LinkedHashSet<>();private boolean below;
  public Walk(long entry){if(BlockPos.of(entry).getY()<0)throw new IllegalArgumentException("Begin above Y0");this.entry=entry;last=entry;visited.add(entry);}
  public boolean step(long next){var a=BlockPos.of(last);var b=BlockPos.of(next);if(Math.abs(a.getX()-b.getX())+Math.abs(a.getZ()-b.getZ())>1||Math.abs(a.getY()-b.getY())>1||visited.size()>=MAX_ROUTE&&!visited.contains(next))return false;last=next;visited.add(next);below|=b.getY()<0;return true;}
  public boolean returned(int required){return below&&last==entry&&visited.size()>=required;}public List<Long> cells(){return List.copyOf(visited);}public long entry(){return entry;}
 }
}
